const raw = $input.first().json.text;
if (typeof raw !== 'string') throw new Error('Model response must be JSON text.');
let parsed;
try { parsed = JSON.parse(raw); } catch { throw new Error('Model response was not valid JSON.'); }
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('Response must be an object.');
if (Object.keys(parsed).some(key => !['intent','parameters','summary','clarification_question'].includes(key))) throw new Error('Response contains unsupported fields.');
const allowed = new Set(['log_activity','create_task','checkin_habit','query_summary','clarify_question']);
if (!allowed.has(parsed.intent)) throw new Error('Unsupported intent.');
if (!parsed.parameters || typeof parsed.parameters !== 'object' || Array.isArray(parsed.parameters)) throw new Error('Parameters must be an object.');
const p = parsed.parameters;
const parameterKeys = { log_activity: ['title','category','duration_minutes','date','notes','timezone'], create_task: ['title','priority','due_date','category','estimated_minutes'], checkin_habit: ['habit_name','checkin_date'], query_summary: ['date_range','category_filter','topic'], clarify_question: [] };
if (Object.keys(p).some(key => !parameterKeys[parsed.intent].includes(key))) throw new Error('Parameters contain unsupported fields.');
const date = value => typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) && !Number.isNaN(Date.parse(value));
const categories = ['work','personal_project','learning','workout','habit','admin','creative','rest','custom'];
if (parsed.intent === 'log_activity' && (typeof p.title !== 'string' || !p.title.trim() || p.title.length > 300 || !categories.includes(p.category) || !Number.isInteger(p.duration_minutes) || p.duration_minutes < 1 || p.duration_minutes > 1440 || !date(p.date) || (p.notes !== undefined && typeof p.notes !== 'string') || (p.timezone !== undefined && typeof p.timezone !== 'string'))) throw new Error('Invalid activity schema.');
if (parsed.intent === 'create_task' && (typeof p.title !== 'string' || !p.title.trim() || p.title.length > 300 || (p.priority !== undefined && !['low','medium','high','urgent'].includes(p.priority)) || (p.category !== undefined && !categories.includes(p.category)) || (p.due_date != null && !date(p.due_date)) || (p.estimated_minutes !== undefined && (!Number.isInteger(p.estimated_minutes) || p.estimated_minutes < 0 || p.estimated_minutes > 100000)))) throw new Error('Invalid task schema.');
if (parsed.intent === 'checkin_habit' && (typeof p.habit_name !== 'string' || !p.habit_name.trim() || p.habit_name.length > 200 || !date(p.checkin_date))) throw new Error('Invalid habit schema.');
if (parsed.intent === 'query_summary' && ((p.date_range !== undefined && !['today','week','month','custom'].includes(p.date_range)) || (p.category_filter !== undefined && p.category_filter !== 'all' && !categories.includes(p.category_filter)) || (p.topic !== undefined && (typeof p.topic !== 'string' || p.topic.length > 300)))) throw new Error('Invalid report schema.');
if (parsed.intent === 'clarify_question' && (typeof parsed.clarification_question !== 'string' || !parsed.clarification_question.trim() || parsed.clarification_question.length > 500)) throw new Error('Invalid clarification schema.');
const request = $('Webhook: Receive Request').first().json.body;
return [{ json: { intent: parsed.intent, parameters: p, summary: typeof parsed.summary === 'string' ? parsed.summary.slice(0, 500) : 'Review the parsed request.', clarification_question: typeof parsed.clarification_question === 'string' ? parsed.clarification_question.slice(0, 500) : null, requestId: request.idempotencyKey } }];
